+
+#define PMD_ALLOC_ORDER		(PMD_SHIFT-PAGE_SHIFT)
+#define PAGES_PER_PMD		(1 << PMD_ALLOC_ORDER)
+
+#define replication_log(data, fmt, args...)		\
+({							\
+	if (data && data->m)				\
+		seq_printf(data->m, fmt, ##args);	\
