+void Hal_GetEfuseDefinition(
+    struct adapter *padapter,
+    u8 efuseType,
+    u8 type,
+    void *pOut
+)
+{
+    switch (type) {
+    case TYPE_EFUSE_MAX_SECTION:
+        {
+            u8 *pMax_section = pOut;
+
+            if (efuseType == EFUSE_WIFI)
+                *pMax_section = EFUSE_MAX_SECTION_8723B;
+            else
+                *pMax_section = EFUSE_BT_MAX_SECTION;
+        }
+        break;
+
+    case TYPE_EFUSE_REAL_CONTENT_LEN:
+        {
+            u16 *pu2Tmp = pOut;
+
+            if (efuseType == EFUSE_WIFI)
+                *pu2Tmp = EFUSE_REAL_CONTENT_LEN_8723B;
+            else
+                *pu2Tmp = EFUSE_BT_REAL_CONTENT_LEN;
+        }
+        break;
+
+    case TYPE_AVAILABLE_EFUSE_BYTES_BANK:
+        {
+            u16 *pu2Tmp = pOut;
+
+            if (efuseType == EFUSE_WIFI)
+                *pu2Tmp = 
(EFUSE_REAL_CONTENT_LEN_8723B-EFUSE_OOB_PROTECT_BYTES);
+            else
+                *pu2Tmp = 
(EFUSE_BT_REAL_BANK_CONTENT_LEN-EFUSE_PROTECT_BYTES_BANK);
+        }
+        break;
+
+    case TYPE_AVAILABLE_EFUSE_BYTES_TOTAL:
+        {
+            u16 *pu2Tmp = pOut;
+
+            if (efuseType == EFUSE_WIFI)
+                *pu2Tmp = 
(EFUSE_REAL_CONTENT_LEN_8723B-EFUSE_OOB_PROTECT_BYTES);
+            else
+                *pu2Tmp = 
(EFUSE_BT_REAL_CONTENT_LEN-(EFUSE_PROTECT_BYTES_BANK*3));
+        }
+        break;
+
+    case TYPE_EFUSE_MAP_LEN:
+        {
+            u16 *pu2Tmp = pOut;
+
+            if (efuseType == EFUSE_WIFI)
+                *pu2Tmp = EFUSE_MAX_MAP_LEN;
+            else
+                *pu2Tmp = EFUSE_BT_MAP_LEN;
+        }
+        break;
+
+    case TYPE_EFUSE_PROTECT_BYTES_BANK:
+        {
+            u8 *pu1Tmp = pOut;
+
+            if (efuseType == EFUSE_WIFI)
+                *pu1Tmp = EFUSE_OOB_PROTECT_BYTES;
+            else
+                *pu1Tmp = EFUSE_PROTECT_BYTES_BANK;
+        }
+        break;
+
+    case TYPE_EFUSE_CONTENT_LEN_BANK:
+        {
+            u16 *pu2Tmp = pOut;
+
+            if (efuseType == EFUSE_WIFI)
+                *pu2Tmp = EFUSE_REAL_CONTENT_LEN_8723B;
+            else
+                *pu2Tmp = EFUSE_BT_REAL_BANK_CONTENT_LEN;
+        }
+        break;
+
+    default:
+        {
+            u8 *pu1Tmp = pOut;
+            *pu1Tmp = 0;
+        }
+        break;
+    }
+}
+
+void Hal_EfusePowerSwitch(
+    struct adapter *padapter, u8 PwrState
+)
+{
+    u8 tempval;
+    u16 tmpV16;
+
+    if (PwrState) {
+        /*  To avoid cannot access efuse registers after disable/enable 
several times during DTM test. */
+        /*  Suggested by SD1 IsaacHsu. 2013.07.08, added by tynli. */
+        tempval = rtw_read8(padapter, 
SDIO_LOCAL_BASE|SDIO_REG_HSUS_CTRL);
+        if (tempval & BIT(0)) { /*  SDIO local register is suspend */
+            u8 count = 0;
+
+            tempval &= ~BIT(0);
+            rtw_write8(padapter, SDIO_LOCAL_BASE|SDIO_REG_HSUS_CTRL, 
tempval);
+
+            /*  check 0x86[1:0]= 10'2h, wait power state to leave 
suspend */
+            do {
+                tempval = rtw_read8(padapter, 
SDIO_LOCAL_BASE|SDIO_REG_HSUS_CTRL);
+                tempval &= 0x3;
+                if (tempval == 0x02)
+                    break;
+
+                count++;
+                if (count >= 100)
+                    break;
+
+                mdelay(10);
+            } while (1);
+        }
+
+        rtw_write8(padapter, REG_EFUSE_ACCESS, EFUSE_ACCESS_ON);
+
+        /*  Reset: 0x0000h[28], default valid */
+        tmpV16 =  rtw_read16(padapter, REG_SYS_FUNC_EN);
+        if (!(tmpV16 & FEN_ELDR)) {
+            tmpV16 |= FEN_ELDR;
+            rtw_write16(padapter, REG_SYS_FUNC_EN, tmpV16);
+        }
+
+        /*  Clock: Gated(0x0008h[5]) 8M(0x0008h[1]) clock from ANA, 
default valid */
+        tmpV16 = rtw_read16(padapter, REG_SYS_CLKR);
+        if ((!(tmpV16 & LOADER_CLK_EN))  || (!(tmpV16 & ANA8M))) {
+            tmpV16 |= (LOADER_CLK_EN | ANA8M);
+            rtw_write16(padapter, REG_SYS_CLKR, tmpV16);
+        }
+    } else {
+        rtw_write8(padapter, REG_EFUSE_ACCESS, EFUSE_ACCESS_OFF);
+    }
+}
+
+static void hal_ReadEFuse_WiFi(
+    struct adapter *padapter,
+    u16 _offset,
+    u16 _size_byte,
+    u8 *pbuf
+)
+{
+    u8 *efuseTbl = NULL;
+    u16 eFuse_Addr = 0;
+    u8 offset, wden;
+    u8 efuseHeader, efuseExtHdr, efuseData;
+    u16 i, total, used;
+    u8 efuse_usage = 0;
+
+    /*  */
+    /*  Do NOT excess total size of EFuse table. Added by Roger, 
2008.11.10. */
+    /*  */
+    if ((_offset + _size_byte) > EFUSE_MAX_MAP_LEN)
+        return;
+
+    efuseTbl = kmalloc(EFUSE_MAX_MAP_LEN, GFP_ATOMIC);
+    if (!efuseTbl)
+        return;
+
+    /*  0xff will be efuse default value instead of 0x00. */
+    memset(efuseTbl, 0xFF, EFUSE_MAX_MAP_LEN);
+
+    /*  switch bank back to bank 0 for later BT and wifi use. */
+    hal_EfuseSwitchToBank(padapter, 0);
+
+    while (AVAILABLE_EFUSE_ADDR(eFuse_Addr)) {
+        rtw_efuse_one_byte_read(padapter, eFuse_Addr++, &efuseHeader);
+        if (efuseHeader == 0xFF)
+            break;
+
+        /*  Check PG header for section num. */
+        if (EXT_HEADER(efuseHeader)) { /* extended header */
+            offset = GET_HDR_OFFSET_2_0(efuseHeader);
+
+            rtw_efuse_one_byte_read(padapter, eFuse_Addr++, 
&efuseExtHdr);
+            if (ALL_WORDS_DISABLED(efuseExtHdr))
+                continue;
+
+            offset |= ((efuseExtHdr & 0xF0) >> 1);
+            wden = (efuseExtHdr & 0x0F);
+        } else {
+            offset = ((efuseHeader >> 4) & 0x0f);
+            wden = (efuseHeader & 0x0f);
+        }
+
+        if (offset < EFUSE_MAX_SECTION_8723B) {
+            u16 addr;
+            /*  Get word enable value from PG header */
+
+            addr = offset * PGPKT_DATA_SIZE;
+            for (i = 0; i < EFUSE_MAX_WORD_UNIT; i++) {
+                /*  Check word enable condition in the section */
+                if (!(wden & (0x01<<i))) {
+                    rtw_efuse_one_byte_read(padapter, eFuse_Addr++,
+                                &efuseData);
+                    efuseTbl[addr] = efuseData;
+
+                    rtw_efuse_one_byte_read(padapter, eFuse_Addr++,
+                                &efuseData);
+                    efuseTbl[addr+1] = efuseData;
+                }
+                addr += 2;
+            }
+        } else {
+            eFuse_Addr += rtw_efuse_calculate_word_counts(wden)*2;
+        }
+    }
+
+    /*  Copy from Efuse map to output pointer memory!!! */
+    for (i = 0; i < _size_byte; i++)
+        pbuf[i] = efuseTbl[_offset+i];
+
+    /*  Calculate Efuse utilization */
+    Hal_GetEfuseDefinition(padapter, EFUSE_WIFI, 
TYPE_AVAILABLE_EFUSE_BYTES_TOTAL, &total);
+    used = eFuse_Addr - 1;
+    efuse_usage = (u8)((used*100)/total);
+
+    rtw_hal_set_hwreg(padapter, HW_VAR_EFUSE_BYTES, (u8 *)&used);
+    rtw_hal_set_hwreg(padapter, HW_VAR_EFUSE_USAGE, (u8 
*)&efuse_usage);
+
+    kfree(efuseTbl);
+}
+
+static void hal_ReadEFuse_BT(
+    struct adapter *padapter,
+    u16 _offset,
+    u16 _size_byte,
+    u8 *pbuf
+)
+{
+    u8 *efuseTbl;
+    u8 bank;
+    u16 eFuse_Addr;
+    u8 efuseHeader, efuseExtHdr, efuseData;
+    u8 offset, wden;
+    u16 i, total, used;
+    u8 efuse_usage;
+
+    /*  */
+    /*  Do NOT excess total size of EFuse table. Added by Roger, 
2008.11.10. */
+    /*  */
+    if ((_offset + _size_byte) > EFUSE_BT_MAP_LEN)
+        return;
+
+    efuseTbl = kmalloc(EFUSE_BT_MAP_LEN, GFP_ATOMIC);
+    if (!efuseTbl)
+        return;
+
+    /*  0xff will be efuse default value instead of 0x00. */
+    memset(efuseTbl, 0xFF, EFUSE_BT_MAP_LEN);
+
+    Hal_GetEfuseDefinition(padapter, EFUSE_BT, 
TYPE_AVAILABLE_EFUSE_BYTES_BANK, &total);
+
+    for (bank = 1; bank < 3; bank++) { /*  8723b Max bake 0~2 */
+        if (!hal_EfuseSwitchToBank(padapter, bank))
+            goto exit;
+
+        eFuse_Addr = 0;
+
+        while (AVAILABLE_EFUSE_ADDR(eFuse_Addr)) {
+            rtw_efuse_one_byte_read(padapter, eFuse_Addr++, 
&efuseHeader);
+            if (efuseHeader == 0xFF)
+                break;
+
+            /*  Check PG header for section num. */
+            if (EXT_HEADER(efuseHeader)) { /* extended header */
+                offset = GET_HDR_OFFSET_2_0(efuseHeader);
+
+                rtw_efuse_one_byte_read(padapter, eFuse_Addr++, 
&efuseExtHdr);
+                if (ALL_WORDS_DISABLED(efuseExtHdr))
+                    continue;
+
+                offset |= ((efuseExtHdr & 0xF0) >> 1);
+                wden = (efuseExtHdr & 0x0F);
+            } else {
+                offset = ((efuseHeader >> 4) & 0x0f);
+                wden = (efuseHeader & 0x0f);
+            }
+
+            if (offset < EFUSE_BT_MAX_SECTION) {
+                u16 addr = offset * PGPKT_DATA_SIZE;
+
+                for (i = 0; i < EFUSE_MAX_WORD_UNIT; i++) {
+                    /*  Check word enable condition in the section */
+                    if (!(wden & (0x01<<i))) {
+                        rtw_efuse_one_byte_read(padapter, eFuse_Addr++,
+                                    &efuseData);
+                        efuseTbl[addr] = efuseData;
+
+                        rtw_efuse_one_byte_read(padapter, eFuse_Addr++,
+                                    &efuseData);
+                        efuseTbl[addr+1] = efuseData;
+                    }
+                    addr += 2;
+                }
+            } else {
+                eFuse_Addr += rtw_efuse_calculate_word_counts(wden)*2;
+            }
+        }
+
+        if ((eFuse_Addr - 1) < total)
+            break;
+
+    }
+
+    /*  switch bank back to bank 0 for later BT and wifi use. */
+    hal_EfuseSwitchToBank(padapter, 0);
+
+    /*  Copy from Efuse map to output pointer memory!!! */
+    for (i = 0; i < _size_byte; i++)
+        pbuf[i] = efuseTbl[_offset+i];
+
+    /*  */
+    /*  Calculate Efuse utilization. */
+    /*  */
+    Hal_GetEfuseDefinition(padapter, EFUSE_BT, 
TYPE_AVAILABLE_EFUSE_BYTES_TOTAL, &total);
+    used = (EFUSE_BT_REAL_BANK_CONTENT_LEN*(bank-1)) + eFuse_Addr - 1;
+    efuse_usage = (u8)((used*100)/total);
+
+    rtw_hal_set_hwreg(padapter, HW_VAR_EFUSE_BT_BYTES, (u8 *)&used);
+    rtw_hal_set_hwreg(padapter, HW_VAR_EFUSE_BT_USAGE, (u8 
*)&efuse_usage);
+
+exit:
+    kfree(efuseTbl);
+}
+
+void Hal_ReadEFuse(
+    struct adapter *padapter,
+    u8 efuseType,
+    u16 _offset,
+    u16 _size_byte,
+    u8 *pbuf
+)
+{
+    if (efuseType == EFUSE_WIFI)
+        hal_ReadEFuse_WiFi(padapter, _offset, _size_byte, pbuf);
+    else
+        hal_ReadEFuse_BT(padapter, _offset, _size_byte, pbuf);
+}
