+void UpdateHalRAMask8723B(struct adapter *padapter, u32 mac_id, u8 
rssi_level)
+{
+    u32 mask, rate_bitmap;
+    u8 short_gi_rate = false;
+    struct sta_info *psta;
+    struct hal_com_data    *pHalData = GET_HAL_DATA(padapter);
+    struct dm_priv *pdmpriv = &pHalData->dmpriv;
+    struct mlme_ext_priv *pmlmeext = &padapter->mlmeextpriv;
+    struct mlme_ext_info *pmlmeinfo = &(pmlmeext->mlmext_info);
+
+    if (mac_id >= NUM_STA) /* CAM_SIZE */
+        return;
+
+    psta = pmlmeinfo->FW_sta_info[mac_id].psta;
+    if (!psta)
+        return;
+
+    short_gi_rate = query_ra_short_GI(psta);
+
+    mask = psta->ra_mask;
+
+    rate_bitmap = 0xffffffff;
+    rate_bitmap = ODM_Get_Rate_Bitmap(&pHalData->odmpriv, mac_id, mask, 
rssi_level);
+
+    mask &= rate_bitmap;
+
+    rate_bitmap = hal_btcoex_GetRaMask(padapter);
+    mask &= ~rate_bitmap;
+
+    if (pHalData->fw_ractrl)
+        rtl8723b_set_FwMacIdConfig_cmd(padapter, mac_id, psta->raid, 
psta->bw_mode, short_gi_rate, mask);
+
+    /* set correct initial date rate for each mac_id */
+    pdmpriv->INIDATA_RATE[mac_id] = psta->init_rate;
+}
