+static void hal_get_chnl_group_8723b(u8 channel, u8 *group)
+{
+    if (channel >= 1 && channel <= 2)
+        *group = 0;
+    else if (channel >= 3 && channel <= 5)
+        *group = 1;
+    else if (channel >= 6 && channel <= 8)
+        *group = 2;
+    else if (channel >= 9 && channel <= 11)
+        *group = 3;
+    else if (channel >= 12 && channel <= 14)
+        *group = 4;
+}
