+    } else {/* autoload fail */
+        if (!pEEPROM->EepromOrEfuse)
+            rtw_efuse_shadow_map_update(padapter, EFUSE_WIFI);
+        memcpy(PROMContent, pEEPROM->efuse_eeprom_data, 
HWSET_MAX_SIZE_8723B);
