+static void Hal_ReadPowerValueFromPROM_8723B(
+    struct adapter *Adapter,
+    struct TxPowerInfo24G *pwrInfo24G,
+    u8 *PROMContent,
+    bool AutoLoadFail
+)
+{
+    u32 rfPath, eeAddr = EEPROM_TX_PWR_INX_8723B, group, TxCount = 0;
+
+    memset(pwrInfo24G, 0, sizeof(struct TxPowerInfo24G));
+
+    if (PROMContent[eeAddr+1] == 0xFF)
+        AutoLoadFail = true;
+
+    if (AutoLoadFail) {
+        for (rfPath = 0; rfPath < MAX_RF_PATH; rfPath++) {
+            /* 2.4G default value */
+            for (group = 0; group < MAX_CHNL_GROUP_24G; group++) {
+                pwrInfo24G->IndexCCK_Base[rfPath][group] = 
EEPROM_DEFAULT_24G_INDEX;
+                pwrInfo24G->IndexBW40_Base[rfPath][group] = 
EEPROM_DEFAULT_24G_INDEX;
+            }
+
+            for (TxCount = 0; TxCount < MAX_TX_COUNT; TxCount++) {
+                if (TxCount == 0) {
+                    pwrInfo24G->BW20_Diff[rfPath][0] = 
EEPROM_DEFAULT_24G_HT20_DIFF;
+                    pwrInfo24G->OFDM_Diff[rfPath][0] = 
EEPROM_DEFAULT_24G_OFDM_DIFF;
+                } else {
+                    pwrInfo24G->BW20_Diff[rfPath][TxCount] = 
EEPROM_DEFAULT_DIFF;
+                    pwrInfo24G->BW40_Diff[rfPath][TxCount] = 
EEPROM_DEFAULT_DIFF;
+                    pwrInfo24G->CCK_Diff[rfPath][TxCount] = 
EEPROM_DEFAULT_DIFF;
+                    pwrInfo24G->OFDM_Diff[rfPath][TxCount] = 
EEPROM_DEFAULT_DIFF;
+                }
+            }
+        }
+
+        return;
+    }
+
+    for (rfPath = 0; rfPath < MAX_RF_PATH; rfPath++) {
+        /* 2 2.4G default value */
+        for (group = 0; group < MAX_CHNL_GROUP_24G; group++) {
+            pwrInfo24G->IndexCCK_Base[rfPath][group] =    
PROMContent[eeAddr++];
+            if (pwrInfo24G->IndexCCK_Base[rfPath][group] == 0xFF)
+                pwrInfo24G->IndexCCK_Base[rfPath][group] = 
EEPROM_DEFAULT_24G_INDEX;
+        }
+
+        for (group = 0; group < MAX_CHNL_GROUP_24G-1; group++) {
+            pwrInfo24G->IndexBW40_Base[rfPath][group] =    
PROMContent[eeAddr++];
+            if (pwrInfo24G->IndexBW40_Base[rfPath][group] == 0xFF)
+                pwrInfo24G->IndexBW40_Base[rfPath][group] =    
EEPROM_DEFAULT_24G_INDEX;
+        }
+
+        for (TxCount = 0; TxCount < MAX_TX_COUNT; TxCount++) {
+            if (TxCount == 0) {
+                pwrInfo24G->BW40_Diff[rfPath][TxCount] = 0;
+                if (PROMContent[eeAddr] == 0xFF)
+                    pwrInfo24G->BW20_Diff[rfPath][TxCount] =    
EEPROM_DEFAULT_24G_HT20_DIFF;
+                else {
+                    pwrInfo24G->BW20_Diff[rfPath][TxCount] =    
(PROMContent[eeAddr]&0xf0)>>4;
+                    if (pwrInfo24G->BW20_Diff[rfPath][TxCount] & 
BIT(3))        /* 4bit sign number to 8 bit sign number */
+                        pwrInfo24G->BW20_Diff[rfPath][TxCount] |= 0xF0;
+                }
+
+                if (PROMContent[eeAddr] == 0xFF)
+                    pwrInfo24G->OFDM_Diff[rfPath][TxCount] = 
EEPROM_DEFAULT_24G_OFDM_DIFF;
+                else {
+                    pwrInfo24G->OFDM_Diff[rfPath][TxCount] = 
(PROMContent[eeAddr]&0x0f);
+                    if (pwrInfo24G->OFDM_Diff[rfPath][TxCount] & 
BIT(3))        /* 4bit sign number to 8 bit sign number */
+                        pwrInfo24G->OFDM_Diff[rfPath][TxCount] |= 0xF0;
+                }
+                pwrInfo24G->CCK_Diff[rfPath][TxCount] = 0;
+                eeAddr++;
+            } else {
+                if (PROMContent[eeAddr] == 0xFF)
+                    pwrInfo24G->BW40_Diff[rfPath][TxCount] = 
EEPROM_DEFAULT_DIFF;
+                else {
+                    pwrInfo24G->BW40_Diff[rfPath][TxCount] = 
(PROMContent[eeAddr]&0xf0)>>4;
+                    if (pwrInfo24G->BW40_Diff[rfPath][TxCount] & 
BIT(3))        /* 4bit sign number to 8 bit sign number */
+                        pwrInfo24G->BW40_Diff[rfPath][TxCount] |= 0xF0;
+                }
+
+                if (PROMContent[eeAddr] == 0xFF)
+                    pwrInfo24G->BW20_Diff[rfPath][TxCount] = 
EEPROM_DEFAULT_DIFF;
+                else {
+                    pwrInfo24G->BW20_Diff[rfPath][TxCount] = 
(PROMContent[eeAddr]&0x0f);
+                    if (pwrInfo24G->BW20_Diff[rfPath][TxCount] & 
BIT(3))        /* 4bit sign number to 8 bit sign number */
+                        pwrInfo24G->BW20_Diff[rfPath][TxCount] |= 0xF0;
+                }
+                eeAddr++;
+
+                if (PROMContent[eeAddr] == 0xFF)
+                    pwrInfo24G->OFDM_Diff[rfPath][TxCount] = 
EEPROM_DEFAULT_DIFF;
+                else {
+                    pwrInfo24G->OFDM_Diff[rfPath][TxCount] = 
(PROMContent[eeAddr]&0xf0)>>4;
+                    if (pwrInfo24G->OFDM_Diff[rfPath][TxCount] & 
BIT(3))        /* 4bit sign number to 8 bit sign number */
+                        pwrInfo24G->OFDM_Diff[rfPath][TxCount] |= 0xF0;
+                }
+
+                if (PROMContent[eeAddr] == 0xFF)
+                    pwrInfo24G->CCK_Diff[rfPath][TxCount] = 
EEPROM_DEFAULT_DIFF;
+                else {
+                    pwrInfo24G->CCK_Diff[rfPath][TxCount] = 
(PROMContent[eeAddr]&0x0f);
+                    if (pwrInfo24G->CCK_Diff[rfPath][TxCount] & BIT(3)) 
        /* 4bit sign number to 8 bit sign number */
+                        pwrInfo24G->CCK_Diff[rfPath][TxCount] |= 0xF0;
+                }
+                eeAddr++;
+            }
+        }
+    }
