+void Hal_EfuseParsePackageType_8723B(
+    struct adapter *padapter, u8 *hwinfo, bool AutoLoadFail
+)
+{
+    struct hal_com_data *pHalData = GET_HAL_DATA(padapter);
+    u8 package;
+    u8 efuseContent;
+
+    Hal_EfusePowerSwitch(padapter, true);
+    rtw_efuse_one_byte_read(padapter, 0x1FB, &efuseContent);
+    Hal_EfusePowerSwitch(padapter, false);
+
+    package = efuseContent & 0x7;
+    switch (package) {
+    case 0x4:
+        pHalData->PackageType = PACKAGE_TFBGA79;
+        break;
+    case 0x5:
+        pHalData->PackageType = PACKAGE_TFBGA90;
+        break;
+    case 0x6:
+        pHalData->PackageType = PACKAGE_QFN68;
+        break;
+    case 0x7:
+        pHalData->PackageType = PACKAGE_TFBGA80;
+        break;
+
+    default:
+        pHalData->PackageType = PACKAGE_DEFAULT;
+        break;
+    }
+}
