+static void rtl8723b_cal_txdesc_chksum(struct tx_desc *ptxdesc)
+{
+    u16 *usPtr = (u16 *)ptxdesc;
+    u32 count;
+    u32 index;
+    u16 checksum = 0;
+
+    /*  Clear first */
+    ptxdesc->txdw7 &= cpu_to_le32(0xffff0000);
+
+    /*  checksum is always calculated by first 32 bytes, */
+    /*  and it doesn't depend on TX DESC length. */
+    /*  Thomas, Lucas@SD4, 20130515 */
+    count = 16;
+
+    for (index = 0; index < count; index++)
+        checksum |= le16_to_cpu(*(__le16 *)(usPtr + index));
+
+    ptxdesc->txdw7 |= cpu_to_le32(checksum & 0x0000ffff);
+}
+
+static u8 fill_txdesc_sectype(struct pkt_attrib *pattrib)
+{
+    u8 sectype = 0;
+
+    if ((pattrib->encrypt > 0) && !pattrib->bswenc) {
+        switch (pattrib->encrypt) {
+        /*  SEC_TYPE */
+        case _WEP40_:
+        case _WEP104_:
+        case _TKIP_:
+        case _TKIP_WTMIC_:
+            sectype = 1;
+            break;
+
+        case _AES_:
+            sectype = 3;
+            break;
+
+        case _NO_PRIVACY_:
+        default:
+            break;
+        }
+    }
+    return sectype;
+}
+
+static void fill_txdesc_vcs_8723b(struct adapter *padapter, struct 
pkt_attrib *pattrib, struct txdesc_8723b *ptxdesc)
+{
+    if (pattrib->vcs_mode) {
+        switch (pattrib->vcs_mode) {
+        case RTS_CTS:
+            ptxdesc->rtsen = 1;
+            /*  ENABLE HW RTS */
+            ptxdesc->hw_rts_en = 1;
+            break;
+
+        case CTS_TO_SELF:
+            ptxdesc->cts2self = 1;
+            break;
+
+        case NONE_VCS:
+        default:
+            break;
+        }
+
+        ptxdesc->rtsrate = 8; /*  RTS Rate =24M */
+        ptxdesc->rts_ratefb_lmt = 0xF;
+
+        if (padapter->mlmeextpriv.mlmext_info.preamble_mode == 
PREAMBLE_SHORT)
+            ptxdesc->rts_short = 1;
+
+        /*  Set RTS BW */
+        if (pattrib->ht_en)
+            ptxdesc->rts_sc = SCMapping_8723B(padapter, pattrib);
+    }
+}
+
+static void fill_txdesc_phy_8723b(struct adapter *padapter, struct 
pkt_attrib *pattrib, struct txdesc_8723b *ptxdesc)
+{
+    if (pattrib->ht_en) {
+        ptxdesc->data_bw = BWMapping_8723B(padapter, pattrib);
+
+        ptxdesc->data_sc = SCMapping_8723B(padapter, pattrib);
+    }
+}
