+/*  */
+/*  Description: In normal chip, we should send some packet to Hw which 
will be used by Fw */
+/*            in FW LPS mode. The function is to fill the Tx descriptor 
of this packets, then */
+/*            Fw can tell Hw to send these packet derectly. */
+/*  Added by tynli. 2009.10.15. */
+/*  */
+/* type1:pspoll, type2:null */
+void rtl8723b_fill_fake_txdesc(
+    struct adapter *padapter,
+    u8 *pDesc,
+    u32 BufferLen,
+    u8 IsPsPoll,
+    u8 IsBTQosNull,
+    u8 bDataFrame
+)
+{
+    /*  Clear all status */
+    memset(pDesc, 0, TXDESC_SIZE);
+
+    SET_TX_DESC_FIRST_SEG_8723B(pDesc, 1); /* bFirstSeg; */
+    SET_TX_DESC_LAST_SEG_8723B(pDesc, 1); /* bLastSeg; */
+
+    SET_TX_DESC_OFFSET_8723B(pDesc, 0x28); /*  Offset = 32 */
+
+    SET_TX_DESC_PKT_SIZE_8723B(pDesc, BufferLen); /*  Buffer size + 
command header */
+    SET_TX_DESC_QUEUE_SEL_8723B(pDesc, QSLT_MGNT); /*  Fixed queue of 
Mgnt queue */
+
+    /*  Set NAVUSEHDR to prevent Ps-poll AId filed to be changed to 
error value by Hw. */
+    if (IsPsPoll) {
+        SET_TX_DESC_NAV_USE_HDR_8723B(pDesc, 1);
+    } else {
+        SET_TX_DESC_HWSEQ_EN_8723B(pDesc, 1); /*  Hw set sequence 
number */
+        SET_TX_DESC_HWSEQ_SEL_8723B(pDesc, 0);
+    }
+
+    if (IsBTQosNull)
+        SET_TX_DESC_BT_INT_8723B(pDesc, 1);
+
+    SET_TX_DESC_USE_RATE_8723B(pDesc, 1); /*  use data rate which is 
set by Sw */
+    SET_TX_DESC_OWN_8723B((u8 *)pDesc, 1);
+
+    SET_TX_DESC_TX_RATE_8723B(pDesc, DESC8723B_RATE1M);
+
+    /*  */
+    /*  Encrypt the data frame if under security mode excepct null 
data. Suggested by CCW. */
+    /*  */
+    if (bDataFrame) {
+        u32 EncAlg = padapter->securitypriv.dot11_privacy_algrthm;
+
+        switch (EncAlg) {
+        case _NO_PRIVACY_:
+            SET_TX_DESC_SEC_TYPE_8723B(pDesc, 0x0);
+            break;
+        case _WEP40_:
+        case _WEP104_:
+        case _TKIP_:
+            SET_TX_DESC_SEC_TYPE_8723B(pDesc, 0x1);
+            break;
+        case _SMS4_:
+            SET_TX_DESC_SEC_TYPE_8723B(pDesc, 0x2);
+            break;
+        case _AES_:
+            SET_TX_DESC_SEC_TYPE_8723B(pDesc, 0x3);
+            break;
+        default:
+            SET_TX_DESC_SEC_TYPE_8723B(pDesc, 0x0);
+            break;
+        }
+    }
+
+    /*  USB interface drop packet if the checksum of descriptor isn't 
correct. */
+    /*  Using this checksum can let hardware recovery from packet bulk 
out error (e.g. Cancel URC, Bulk out error.). */
+    rtl8723b_cal_txdesc_chksum((struct tx_desc *)pDesc);
+}
+
+static void hw_var_set_opmode(struct adapter *padapter, u8 variable, u8 
*val)
+{
+    u8 val8;
+    u8 mode = *((u8 *)val);
+
+    {
+        /*  disable Port0 TSF update */
+        val8 = rtw_read8(padapter, REG_BCN_CTRL);
+        val8 |= DIS_TSF_UDT;
+        rtw_write8(padapter, REG_BCN_CTRL, val8);
+
+        /*  set net_type */
+        set_msr(padapter, mode);
+
+        if ((mode == _HW_STATE_STATION_) || (mode == 
_HW_STATE_NOLINK_)) {
+            {
+                StopTxBeacon(padapter);
+            }
+
+            /*  disable atim wnd */
+            rtw_write8(padapter, REG_BCN_CTRL, 
DIS_TSF_UDT|EN_BCN_FUNCTION|DIS_ATIM);
+            /* rtw_write8(padapter, REG_BCN_CTRL, 0x18); */
+        } else if (mode == _HW_STATE_ADHOC_) {
+            ResumeTxBeacon(padapter);
+            rtw_write8(padapter, REG_BCN_CTRL, 
DIS_TSF_UDT|EN_BCN_FUNCTION|DIS_BCNQ_SUB);
+        } else if (mode == _HW_STATE_AP_) {
+
+            ResumeTxBeacon(padapter);
+
+            rtw_write8(padapter, REG_BCN_CTRL, 
DIS_TSF_UDT|DIS_BCNQ_SUB);
+
+            /* Set RCR */
+            rtw_write32(padapter, REG_RCR, 0x7000208e);/* CBSSID_DATA 
must set to 0, reject ICV_ERR packet */
+            /* enable to rx data frame */
+            rtw_write16(padapter, REG_RXFLTMAP2, 0xFFFF);
+            /* enable to rx ps-poll */
+            rtw_write16(padapter, REG_RXFLTMAP1, 0x0400);
+
+            /* Beacon Control related register for first time */
+            rtw_write8(padapter, REG_BCNDMATIM, 0x02); /*  2ms */
+
+            /* rtw_write8(padapter, REG_BCN_MAX_ERR, 0xFF); */
+            rtw_write8(padapter, REG_ATIMWND, 0x0a); /*  10ms */
+            rtw_write16(padapter, REG_BCNTCFG, 0x00);
+            rtw_write16(padapter, REG_TBTT_PROHIBIT, 0xff04);
+            rtw_write16(padapter, REG_TSFTR_SYN_OFFSET, 0x7fff);/*  
+32767 (~32ms) */
+
+            /* reset TSF */
+            rtw_write8(padapter, REG_DUAL_TSF_RST, BIT(0));
+
+            /* enable BCN0 Function for if1 */
+            /* don't enable update TSF0 for if1 (due to TSF update when 
beacon/probe rsp are received) */
+            rtw_write8(padapter, REG_BCN_CTRL, 
(DIS_TSF_UDT|EN_BCN_FUNCTION|EN_TXBCN_RPT|DIS_BCNQ_SUB));
+
+            /* SW_BCN_SEL - Port0 */
+            /* rtw_write8(Adapter, REG_DWBCN1_CTRL_8192E+2, 
rtw_read8(Adapter, REG_DWBCN1_CTRL_8192E+2) & ~BIT4); */
+            rtw_hal_set_hwreg(padapter, HW_VAR_DL_BCN_SEL, NULL);
+
+            /*  select BCN on port 0 */
+            rtw_write8(
+                padapter,
+                REG_CCK_CHECK_8723B,
+                (rtw_read8(padapter, 
REG_CCK_CHECK_8723B)&~BIT_BCN_PORT_SEL)
+            );
+
+            /*  dis BCN1 ATIM  WND if if2 is station */
+            val8 = rtw_read8(padapter, REG_BCN_CTRL_1);
+            val8 |= DIS_ATIM;
+            rtw_write8(padapter, REG_BCN_CTRL_1, val8);
+        }
+    }
+}
