+static void hw_var_set_bssid(struct adapter *padapter, u8 variable, u8 
*val)
+{
+    u8 idx = 0;
+    u32 reg_bssid = REG_BSSID;
+
+    for (idx = 0 ; idx < 6; idx++)
+        rtw_write8(padapter, (reg_bssid+idx), val[idx]);
+}
