LE_BITS_TO_1BYTE((_Header + 0), 7, 1)
+
+    if (GET_8723B_C2H_TX_RPT_RETRY_OVER(pdata) | 
GET_8723B_C2H_TX_RPT_LIFE_TIME_OVER(pdata))
+        rtw_ack_tx_done(&padapter->xmitpriv, 
RTW_SCTX_DONE_CCX_PKT_FAIL);
