+void SetHwReg8723B(struct adapter *padapter, u8 variable, u8 *val)
+{
+    struct hal_com_data *pHalData = GET_HAL_DATA(padapter);
+    u8 val8;
+    u32 val32;
+
+    switch (variable) {
+    case HW_VAR_MEDIA_STATUS:
+        val8 = rtw_read8(padapter, MSR) & 0x0c;
+        val8 |= *val;
+        rtw_write8(padapter, MSR, val8);
+        break;
+
+    case HW_VAR_MEDIA_STATUS1:
+        val8 = rtw_read8(padapter, MSR) & 0x03;
+        val8 |= *val << 2;
+        rtw_write8(padapter, MSR, val8);
+        break;
+
+    case HW_VAR_SET_OPMODE:
+        hw_var_set_opmode(padapter, variable, val);
+        break;
+
+    case HW_VAR_MAC_ADDR:
+        hw_var_set_macaddr(padapter, variable, val);
+        break;
+
+    case HW_VAR_BSSID:
+        hw_var_set_bssid(padapter, variable, val);
+        break;
+
+    case HW_VAR_BASIC_RATE:
+    {
+        struct mlme_ext_info *mlmext_info = 
&padapter->mlmeextpriv.mlmext_info;
+        u16 BrateCfg = 0;
+        u16 rrsr_2g_force_mask = (RRSR_11M|RRSR_5_5M|RRSR_1M);
+        u16 rrsr_2g_allow_mask = 
(RRSR_24M|RRSR_12M|RRSR_6M|RRSR_CCK_RATES);
+
+        HalSetBrateCfg(padapter, val, &BrateCfg);
+
+        /* apply force and allow mask */
+        BrateCfg |= rrsr_2g_force_mask;
+        BrateCfg &= rrsr_2g_allow_mask;
+
+        /* IOT consideration */
+        if (mlmext_info->assoc_AP_vendor == HT_IOT_PEER_CISCO) {
+            /* if peer is cisco and didn't use ofdm rate, we enable 6M 
ack */
+            if ((BrateCfg & (RRSR_24M|RRSR_12M|RRSR_6M)) == 0)
+                BrateCfg |= RRSR_6M;
+        }
+
+        pHalData->BasicRateSet = BrateCfg;
+
+        /*  Set RRSR rate table. */
+        rtw_write16(padapter, REG_RRSR, BrateCfg);
+        rtw_write8(padapter, REG_RRSR+2, rtw_read8(padapter, 
REG_RRSR+2)&0xf0);
+    }
+        break;
+
+    case HW_VAR_TXPAUSE:
+        rtw_write8(padapter, REG_TXPAUSE, *val);
+        break;
+
+    case HW_VAR_BCN_FUNC:
+        hw_var_set_bcn_func(padapter, variable, val);
+        break;
+
+    case HW_VAR_CORRECT_TSF:
+        hw_var_set_correct_tsf(padapter, variable, val);
+        break;
+
+    case HW_VAR_CHECK_BSSID:
+        {
+            u32 val32;
+
+            val32 = rtw_read32(padapter, REG_RCR);
+            if (*val)
+                val32 |= RCR_CBSSID_DATA|RCR_CBSSID_BCN;
+            else
+                val32 &= ~(RCR_CBSSID_DATA|RCR_CBSSID_BCN);
+            rtw_write32(padapter, REG_RCR, val32);
+        }
+        break;
+
+    case HW_VAR_MLME_DISCONNECT:
+        hw_var_set_mlme_disconnect(padapter, variable, val);
+        break;
+
+    case HW_VAR_MLME_SITESURVEY:
+        hw_var_set_mlme_sitesurvey(padapter, variable,  val);
+
+        hal_btcoex_ScanNotify(padapter, *val?true:false);
+        break;
+
+    case HW_VAR_MLME_JOIN:
+        hw_var_set_mlme_join(padapter, variable, val);
+
+        switch (*val) {
+        case 0:
+            /*  prepare to join */
+            hal_btcoex_ConnectNotify(padapter, true);
+            break;
+        case 1:
+            /*  joinbss_event callback when join res < 0 */
+            hal_btcoex_ConnectNotify(padapter, false);
+            break;
+        case 2:
+            /*  sta add event callback */
+/*                 rtw_btcoex_MediaStatusNotify(padapter, 
RT_MEDIA_CONNECT); */
+            break;
+        }
+        break;
+
+    case HW_VAR_ON_RCR_AM:
+        val32 = rtw_read32(padapter, REG_RCR);
+        val32 |= RCR_AM;
+        rtw_write32(padapter, REG_RCR, val32);
+        break;
+
+    case HW_VAR_OFF_RCR_AM:
+        val32 = rtw_read32(padapter, REG_RCR);
+        val32 &= ~RCR_AM;
+        rtw_write32(padapter, REG_RCR, val32);
+        break;
+
+    case HW_VAR_BEACON_INTERVAL:
+        rtw_write16(padapter, REG_BCN_INTERVAL, *((u16 *)val));
+        break;
+
+    case HW_VAR_SLOT_TIME:
+        rtw_write8(padapter, REG_SLOT, *val);
+        break;
+
+    case HW_VAR_RESP_SIFS:
+        /* SIFS_Timer = 0x0a0a0808; */
+        /* RESP_SIFS for CCK */
+        rtw_write8(padapter, REG_RESP_SIFS_CCK, val[0]); /*  
SIFS_T2T_CCK (0x08) */
+        rtw_write8(padapter, REG_RESP_SIFS_CCK+1, val[1]); /* 
SIFS_R2T_CCK(0x08) */
+        /* RESP_SIFS for OFDM */
+        rtw_write8(padapter, REG_RESP_SIFS_OFDM, val[2]); /* 
SIFS_T2T_OFDM (0x0a) */
+        rtw_write8(padapter, REG_RESP_SIFS_OFDM+1, val[3]); /* 
SIFS_R2T_OFDM(0x0a) */
+        break;
+
+    case HW_VAR_ACK_PREAMBLE:
+        {
+            u8 regTmp = 0;
+            u8 bShortPreamble = *val;
+
+            /*  Joseph marked out for Netgear 3500 TKIP channel 7 
issue.(Temporarily) */
+            /* regTmp = (pHalData->nCur40MhzPrimeSC)<<5; */
+            if (bShortPreamble)
+                regTmp |= 0x80;
+            rtw_write8(padapter, REG_RRSR+2, regTmp);
+        }
+        break;
+
+    case HW_VAR_CAM_EMPTY_ENTRY:
+        {
+            u8 ucIndex = *val;
+            u8 i;
+            u32 ulCommand = 0;
+            u32 ulContent = 0;
+            u32 ulEncAlgo = CAM_AES;
+
+            for (i = 0; i < CAM_CONTENT_COUNT; i++) {
+                /*  filled id in CAM config 2 byte */
+                if (i == 0) {
+                    ulContent |= (ucIndex & 0x03) | 
((u16)(ulEncAlgo)<<2);
+                    /* ulContent |= CAM_VALID; */
+                } else
+                    ulContent = 0;
+
+                /*  polling bit, and No Write enable, and address */
+                ulCommand = CAM_CONTENT_COUNT*ucIndex+i;
+                ulCommand = ulCommand | CAM_POLLINIG | CAM_WRITE;
+                /*  write content 0 is equal to mark as invalid */
+                rtw_write32(padapter, WCAMI, ulContent);  /* 
mdelay(40); */
+                rtw_write32(padapter, RWCAM, ulCommand);  /* 
mdelay(40); */
+            }
+        }
+        break;
+
+    case HW_VAR_CAM_INVALID_ALL:
+        rtw_write32(padapter, RWCAM, BIT(31)|BIT(30));
+        break;
+
+    case HW_VAR_CAM_WRITE:
+        {
+            u32 cmd;
+            u32 *cam_val = (u32 *)val;
+
+            rtw_write32(padapter, WCAMI, cam_val[0]);
+
+            cmd = CAM_POLLINIG | CAM_WRITE | cam_val[1];
+            rtw_write32(padapter, RWCAM, cmd);
+        }
+        break;
+
+    case HW_VAR_AC_PARAM_VO:
+        rtw_write32(padapter, REG_EDCA_VO_PARAM, *((u32 *)val));
+        break;
+
+    case HW_VAR_AC_PARAM_VI:
+        rtw_write32(padapter, REG_EDCA_VI_PARAM, *((u32 *)val));
+        break;
+
+    case HW_VAR_AC_PARAM_BE:
+        pHalData->AcParam_BE = ((u32 *)(val))[0];
+        rtw_write32(padapter, REG_EDCA_BE_PARAM, *((u32 *)val));
+        break;
+
+    case HW_VAR_AC_PARAM_BK:
+        rtw_write32(padapter, REG_EDCA_BK_PARAM, *((u32 *)val));
+        break;
+
+    case HW_VAR_ACM_CTRL:
+        {
+            u8 ctrl = *((u8 *)val);
+            u8 hwctrl = 0;
+
+            if (ctrl != 0) {
+                hwctrl |= AcmHw_HwEn;
+
+                if (ctrl & BIT(1)) /*  BE */
+                    hwctrl |= AcmHw_BeqEn;
+
+                if (ctrl & BIT(2)) /*  VI */
+                    hwctrl |= AcmHw_ViqEn;
+
+                if (ctrl & BIT(3)) /*  VO */
+                    hwctrl |= AcmHw_VoqEn;
+            }
+
+            rtw_write8(padapter, REG_ACMHWCTRL, hwctrl);
+        }
+        break;
+
+    case HW_VAR_AMPDU_FACTOR:
+        {
+            u32 AMPDULen =  (*((u8 *)val));
+
+            if (AMPDULen < HT_AGG_SIZE_32K)
+                AMPDULen = (0x2000 << (*((u8 *)val)))-1;
+            else
+                AMPDULen = 0x7fff;
+
+            rtw_write32(padapter, REG_AMPDU_MAX_LENGTH_8723B, 
AMPDULen);
+        }
+        break;
+
+    case HW_VAR_H2C_FW_PWRMODE:
+        {
+            u8 psmode = *val;
+
+            /*  Forece leave RF low power mode for 1T1R to prevent 
conficting setting in Fw power */
+            /*  saving sequence. 2010.06.07. Added by tynli. Suggested 
by SD3 yschang. */
+            if (psmode != PS_MODE_ACTIVE)
+                ODM_RF_Saving(&pHalData->odmpriv, true);
+
+            /* if (psmode != PS_MODE_ACTIVE)    { */
+            /*     rtl8723b_set_lowpwr_lps_cmd(padapter, true); */
+            /*  else { */
+            /*     rtl8723b_set_lowpwr_lps_cmd(padapter, false); */
+            /*  */
+            rtl8723b_set_FwPwrMode_cmd(padapter, psmode);
+        }
+        break;
+    case HW_VAR_H2C_PS_TUNE_PARAM:
+        rtl8723b_set_FwPsTuneParam_cmd(padapter);
+        break;
+
+    case HW_VAR_H2C_FW_JOINBSSRPT:
+        rtl8723b_set_FwJoinBssRpt_cmd(padapter, *val);
+        break;
+
+    case HW_VAR_INITIAL_GAIN:
+        {
+            struct dig_t *pDigTable = &pHalData->odmpriv.DM_DigTable;
+            u32 rx_gain = *(u32 *)val;
+
+            if (rx_gain == 0xff) {/* restore rx gain */
+                ODM_Write_DIG(&pHalData->odmpriv, 
pDigTable->BackupIGValue);
+            } else {
+                pDigTable->BackupIGValue = pDigTable->CurIGValue;
+                ODM_Write_DIG(&pHalData->odmpriv, rx_gain);
+            }
+        }
+        break;
+
+    case HW_VAR_EFUSE_USAGE:
+        pHalData->EfuseUsedPercentage = *val;
+        break;
+
+    case HW_VAR_EFUSE_BYTES:
+        pHalData->EfuseUsedBytes = *((u16 *)val);
+        break;
+
+    case HW_VAR_EFUSE_BT_USAGE:
+#ifdef HAL_EFUSE_MEMORY
+        pHalData->EfuseHal.BTEfuseUsedPercentage = *val;
+#endif
+        break;
+
+    case HW_VAR_EFUSE_BT_BYTES:
+#ifdef HAL_EFUSE_MEMORY
+        pHalData->EfuseHal.BTEfuseUsedBytes = *((u16 *)val);
+#else
+        BTEfuseUsedBytes = *((u16 *)val);
+#endif
+        break;
+
+    case HW_VAR_FIFO_CLEARN_UP:
+        {
+            #define RW_RELEASE_EN        BIT(18)
+            #define RXDMA_IDLE            BIT(17)
+
+            struct pwrctrl_priv *pwrpriv = adapter_to_pwrctl(padapter);
+            u8 trycnt = 100;
+
+            /*  pause tx */
+            rtw_write8(padapter, REG_TXPAUSE, 0xff);
+
+            /*  keep sn */
+            padapter->xmitpriv.nqos_ssn = rtw_read16(padapter, 
REG_NQOS_SEQ);
+
+            if (!pwrpriv->bkeepfwalive) {
+                /* RX DMA stop */
+                val32 = rtw_read32(padapter, REG_RXPKT_NUM);
+                val32 |= RW_RELEASE_EN;
+                rtw_write32(padapter, REG_RXPKT_NUM, val32);
+                do {
+                    val32 = rtw_read32(padapter, REG_RXPKT_NUM);
+                    val32 &= RXDMA_IDLE;
+                    if (val32)
+                        break;
+                } while (--trycnt);
+
+                /*  RQPN Load 0 */
+                rtw_write16(padapter, REG_RQPN_NPQ, 0);
+                rtw_write32(padapter, REG_RQPN, 0x80000000);
+                mdelay(2);
+            }
+        }
+        break;
+
+    case HW_VAR_APFM_ON_MAC:
+        pHalData->bMacPwrCtrlOn = *val;
+        break;
+
+    case HW_VAR_NAV_UPPER:
+        {
+            u32 usNavUpper = *((u32 *)val);
+
+            if (usNavUpper > HAL_NAV_UPPER_UNIT_8723B * 0xFF)
+                break;
+
+            usNavUpper = DIV_ROUND_UP(usNavUpper,
+                          HAL_NAV_UPPER_UNIT_8723B);
+            rtw_write8(padapter, REG_NAV_UPPER, (u8)usNavUpper);
+        }
+        break;
+
+    case HW_VAR_H2C_MEDIA_STATUS_RPT:
+        {
+            u16 mstatus_rpt = (*(u16 *)val);
+            u8 mstatus, macId;
+
+            mstatus = (u8) (mstatus_rpt & 0xFF);
+            macId = (u8)(mstatus_rpt >> 8);
+            rtl8723b_set_FwMediaStatusRpt_cmd(padapter, mstatus, 
macId);
+        }
+        break;
+    case HW_VAR_BCN_VALID:
+        {
+            /*  BCN_VALID, BIT16 of REG_TDECTRL = BIT0 of 
REG_TDECTRL+2, write 1 to clear, Clear by sw */
+            val8 = rtw_read8(padapter, REG_TDECTRL+2);
+            val8 |= BIT(0);
+            rtw_write8(padapter, REG_TDECTRL+2, val8);
+        }
+        break;
+
+    case HW_VAR_DL_BCN_SEL:
+        {
+            /*  SW_BCN_SEL - Port0 */
+            val8 = rtw_read8(padapter, REG_DWBCN1_CTRL_8723B+2);
+            val8 &= ~BIT(4);
+            rtw_write8(padapter, REG_DWBCN1_CTRL_8723B+2, val8);
+        }
+        break;
+
+    case HW_VAR_DL_RSVD_PAGE:
+        if (check_fwstate(&padapter->mlmepriv, WIFI_AP_STATE))
+            rtl8723b_download_BTCoex_AP_mode_rsvd_page(padapter);
+        else
+            rtl8723b_download_rsvd_page(padapter, RT_MEDIA_CONNECT);
+        break;
+
+    case HW_VAR_MACID_SLEEP:
+        /*  Input is MACID */
+        val32 = *(u32 *)val;
+        if (val32 > 31)
+            break;
+
+        val8 = (u8)val32; /*  macid is between 0~31 */
+
+        val32 = rtw_read32(padapter, REG_MACID_SLEEP);
+        if (val32 & BIT(val8))
+            break;
+        val32 |= BIT(val8);
+        rtw_write32(padapter, REG_MACID_SLEEP, val32);
+        break;
+
+    case HW_VAR_MACID_WAKEUP:
+        /*  Input is MACID */
+        val32 = *(u32 *)val;
+        if (val32 > 31)
+            break;
+
+        val8 = (u8)val32; /*  macid is between 0~31 */
+
+        val32 = rtw_read32(padapter, REG_MACID_SLEEP);
+        if (!(val32 & BIT(val8)))
+            break;
+        val32 &= ~BIT(val8);
+        rtw_write32(padapter, REG_MACID_SLEEP, val32);
+        break;
+
+    default:
+        SetHwReg(padapter, variable, val);
+        break;
+    }
+}
+
+void GetHwReg8723B(struct adapter *padapter, u8 variable, u8 *val)
+{
+    struct hal_com_data *pHalData = GET_HAL_DATA(padapter);
+    u8 val8;
+    u16 val16;
+
+    switch (variable) {
+    case HW_VAR_TXPAUSE:
+        *val = rtw_read8(padapter, REG_TXPAUSE);
+        break;
+
+    case HW_VAR_BCN_VALID:
+        {
+            /*  BCN_VALID, BIT16 of REG_TDECTRL = BIT0 of REG_TDECTRL+2 
*/
+            val8 = rtw_read8(padapter, REG_TDECTRL+2);
+            *val = (BIT(0) & val8) ? true : false;
+        }
+        break;
+
+    case HW_VAR_FWLPS_RF_ON:
+        {
+            /*  When we halt NIC, we should check if FW LPS is leave. 
*/
+            u32 valRCR;
+
+            if (
+                padapter->bSurpriseRemoved  ||
+                (adapter_to_pwrctl(padapter)->rf_pwrstate == rf_off)
+            ) {
+                /*  If it is in HW/SW Radio OFF or IPS state, we do not 
check Fw LPS Leave, */
+                /*  because Fw is unload. */
+                *val = true;
+            } else {
+                valRCR = rtw_read32(padapter, REG_RCR);
+                valRCR &= 0x00070000;
+                if (valRCR)
+                    *val = false;
+                else
+                    *val = true;
+            }
+        }
+        break;
+
+    case HW_VAR_EFUSE_USAGE:
+        *val = pHalData->EfuseUsedPercentage;
+        break;
+
+    case HW_VAR_EFUSE_BYTES:
+        *((u16 *)val) = pHalData->EfuseUsedBytes;
+        break;
+
+    case HW_VAR_EFUSE_BT_USAGE:
+#ifdef HAL_EFUSE_MEMORY
+        *val = pHalData->EfuseHal.BTEfuseUsedPercentage;
+#endif
+        break;
+
+    case HW_VAR_EFUSE_BT_BYTES:
+#ifdef HAL_EFUSE_MEMORY
+        *((u16 *)val) = pHalData->EfuseHal.BTEfuseUsedBytes;
+#else
+        *((u16 *)val) = BTEfuseUsedBytes;
+#endif
+        break;
+
+    case HW_VAR_APFM_ON_MAC:
+        *val = pHalData->bMacPwrCtrlOn;
+        break;
+    case HW_VAR_CHK_HI_QUEUE_EMPTY:
+        val16 = rtw_read16(padapter, REG_TXPKT_EMPTY);
+        *val = (val16 & BIT(10)) ? true : false;
+        break;
+    default:
+        GetHwReg(padapter, variable, val);
+        break;
+    }
+}
+
+/* Description:
+ *    Query setting of specified variable.
+ */
+u8 GetHalDefVar8723B(struct adapter *padapter, enum hal_def_variable 
variable, void *pval)
+{
+    u8 bResult = _SUCCESS;
+
+    switch (variable) {
+    case HAL_DEF_MAX_RECVBUF_SZ:
+        *((u32 *)pval) = MAX_RECVBUF_SZ;
+        break;
+
+    case HAL_DEF_RX_PACKET_OFFSET:
+        *((u32 *)pval) = RXDESC_SIZE + DRVINFO_SZ*8;
+        break;
+
+    case HW_VAR_MAX_RX_AMPDU_FACTOR:
+        /*  Stanley@BB.SD3 suggests 16K can get stable performance */
+        /*  The experiment was done on SDIO interface */
+        /*  coding by Lucas@20130730 */
+        *(u32 *)pval = IEEE80211_HT_MAX_AMPDU_16K;
+        break;
+    case HAL_DEF_TX_LDPC:
+    case HAL_DEF_RX_LDPC:
+        *((u8 *)pval) = false;
+        break;
+    case HAL_DEF_TX_STBC:
+        *((u8 *)pval) = 0;
+        break;
+    case HAL_DEF_RX_STBC:
+        *((u8 *)pval) = 1;
+        break;
+    case HAL_DEF_EXPLICIT_BEAMFORMER:
+    case HAL_DEF_EXPLICIT_BEAMFORMEE:
+        *((u8 *)pval) = false;
+        break;
+
+    case HW_DEF_RA_INFO_DUMP:
+        {
+            u8 mac_id = *(u8 *)pval;
+            u32 cmd = 0x40000100 | mac_id;
+
+            rtw_write32(padapter, REG_HMEBOX_DBG_2_8723B, cmd);
+            msleep(10);
+            rtw_read32(padapter, 0x2F0);    // info 1
+
+            cmd = 0x40000400 | mac_id;
+            rtw_write32(padapter, REG_HMEBOX_DBG_2_8723B, cmd);
+            msleep(10);
+            rtw_read32(padapter, 0x2F0);    // info 1
+            rtw_read32(padapter, 0x2F4);    // info 2
+            rtw_read32(padapter, 0x2F8);    // rate mask 1
+            rtw_read32(padapter, 0x2FC);    // rate mask 2
+        }
+        break;
+
+    case HAL_DEF_TX_PAGE_BOUNDARY:
+        if (!padapter->registrypriv.wifi_spec) {
+            *(u8 *)pval = TX_PAGE_BOUNDARY_8723B;
+        } else {
+            *(u8 *)pval = WMM_NORMAL_TX_PAGE_BOUNDARY_8723B;
+        }
+        break;
+
+    case HAL_DEF_MACID_SLEEP:
+        *(u8 *)pval = true; /*  support macid sleep */
+        break;
+
+    default:
+        bResult = GetHalDefVar(padapter, variable, pval);
+        break;
+    }
+
+    return bResult;
+}
