+		if (tier_dist) {
+			int *d;
+
+			rcu_read_lock();
+			d = rcu_dereference(sched_numa_node_distance);
+			if (d)
+				memcpy(tier_dist, d, nr_tiers * sizeof(int));
+			else
+				nr_tiers = 0;
+			rcu_read_unlock();
+		} else {
