+	if (!tier_dist) {
+		/*
+		 * NUMA distance tiers not available yet (e.g. very early
+		 * boot or a non-NUMA build): fall back to the raw
+		 * node_distance() table, same as sched_cache_node_distance()
+		 * would have returned anyway.
